$make = function ($requestId, $owner, $key) use ($db, $actor, $fac) { $db->query('INSERT INTO requests (request_id,user_id,location,request_status,assigned_puskesmas_code,assigned_puskesmas_name,consultation_mode,responsible_doctor_user_id) VALUES (?,?,?,?,?,?,?,?)', array($requestId, $owner, 'synthetic', 'Accepted', $fac, 'Task 10 Concurrency', 'non_visit', $actor)); $db->query('INSERT INTO request_responsible_doctor_assignments (request_id,staff_id,user_id,assigned_by_user_id,status,assigned_at) VALUES (?,?,?,?,?,NOW(6))', array($requestId, $actor, $actor, $actor, 'aktif')); $db->query('INSERT INTO visit_dispositions (request_id,version_no,decision,urgency,created_by_user_id,idempotency_key,created_at) VALUES (?,?,?,?,?,?,NOW(6))', array($requestId, 1, 'non_visit', null, $actor, $key)); $db->query('INSERT INTO medicalrecords (request_id,diagnosis,treatment,recommendations,anamnesis,responsible_doctor_user_id,recorded_by_user_id,clinical_finalized_at,clinical_finalized_by_user_id) VALUES (?,?,?,?,?,?,?,NOW(6),?)', array($requestId, 'd', 't', 'r', 'a', $actor, $actor, $actor)); };
$collect = function ($p, $pipes) { foreach ($pipes as $h) { stream_set_blocking($h, false); } $deadline = microtime(true) + 12; $out = ''; $err = ''; while (microtime(true) < $deadline) { $out .= stream_get_contents($pipes[1]); $err .= stream_get_contents($pipes[2]); $st = proc_get_status($p); if (!$st['running']) { $out .= stream_get_contents($pipes[1]); $err .= stream_get_contents($pipes[2]); break; } usleep(20000); } if (is_resource($p) && proc_get_status($p)['running']) proc_terminate($p); foreach ($pipes as $h) if (is_resource($h)) fclose($h); if (is_resource($p)) proc_close($p); $decoded = json_decode(trim($out), true) ?: array(); if ($err !== '') { $decoded['_stderr'] = trim($err); } return $decoded; };
 $fixtureFingerprint = function ($requestId, $actor, $mode) use ($db) { $request = $db->select('request_id,user_id,request_status,assigned_puskesmas_code,consultation_mode,visit_status')->where('request_id', $requestId)->get('requests')->row_array(); $disposition = $db->select('disposition_id,version_no,decision')->where('request_id', $requestId)->order_by('version_no', 'DESC')->limit(1)->get('visit_dispositions')->row_array(); $responsible = $db->select('responsible_assignment_id,user_id,staff_id,status')->where('request_id', $requestId)->where('status', 'aktif')->order_by('responsible_assignment_id', 'DESC')->limit(1)->get('request_responsible_doctor_assignments')->row_array(); $record = $db->select('record_id,clinical_finalized_at,clinical_finalized_by_user_id')->where('request_id', $requestId)->order_by('record_id', 'DESC')->limit(1)->get('medicalrecords')->row_array(); $user = $db->select('userId,role,status')->where('userId', $actor)->get('users')->row_array(); $staff = $db->select('staff_id,user_id,profesi,status,kode_pkm')->where('user_id', $actor)->order_by('staff_id', 'DESC')->limit(1)->get('puskesmas_staff')->row_array(); $result = $db->select('visit_result_id,visit_assignment_id,performer_user_id,performer_staff_id,status')->where('request_id', $requestId)->where('status', 'submitted')->order_by('visit_result_id', 'DESC')->limit(1)->get('visit_results')->row_array(); $review = $result ? $db->select('clinical_review_id,decision')->where('visit_result_id', (int) $result['visit_result_id'])->get('clinical_reviews')->row_array() : array(); $assignment = $result ? $db->select('visit_assignment_id,user_id,staff_id,status')->where('visit_assignment_id', (int) $result['visit_assignment_id'])->get('request_visit_performer_assignments')->row_array() : array(); return hash('sha256', json_encode(array('request' => $request, 'disposition' => $disposition, 'responsible' => $responsible, 'record' => array('record_id' => $record['record_id'] ?? null, 'finalized' => !empty($record['clinical_finalized_at']), 'finalized_by' => $record['clinical_finalized_by_user_id'] ?? null), 'user' => $user, 'staff' => $staff, 'result' => $result, 'review' => $review, 'assignment' => $assignment, 'mode' => $mode), JSON_UNESCAPED_SLASHES)); };
$barrierRace = function ($workers) use ($collect, $fixtureFingerprint) { $runId = bin2hex(random_bytes(8)); $scenarioId = 'closure-' . bin2hex(random_bytes(6)); $dir = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'doclinc-closure-race-' . $runId . '-' . $scenarioId; if (!mkdir($dir, 0700, true)) { throw new RuntimeException('BARRIER_PROTOCOL_SETUP_FAILED'); } $procs = array(); $envBase = getenv(); try { foreach ($workers as $i => $worker) { $id = $i === 0 ? 'A' : 'B'; $env = array_merge($envBase, array('TASK10_BARRIER_DIR' => $dir, 'TASK10_RUN_ID' => $runId, 'TASK10_SCENARIO_ID' => $scenarioId, 'TASK10_WORKER_ID' => $id)); $pipes = array(); $cmd = escapeshellarg(PHP_BINARY) . ' ' . escapeshellarg(__DIR__ . '/clinical_closure_worker.php') . ' ' . $worker[0] . ' ' . $worker[1] . ' ' . $worker[2] . ' ' . escapeshellarg($worker[3]); $p = proc_open($cmd, array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')), $pipes, __DIR__, $env); $procs[] = array($p, $pipes); } $deadline = microtime(true) + 10; $ready = array(); while (microtime(true) < $deadline && count($ready) < 2) { foreach (array('A','B') as $id) { $path = $dir . DIRECTORY_SEPARATOR . 'ready-' . $id . '.json'; if (is_file($path) && !isset($ready[$id])) { $ready[$id] = json_decode((string) file_get_contents($path), true); } } if (count($ready) < 2) usleep(10000); } if (count($ready) !== 2) { throw new RuntimeException('BARRIER_PROTOCOL_MISSING_READY'); } foreach ($ready as $id => $payload) { if (!is_array($payload) || ($payload['run_id'] ?? '') !== $runId || ($payload['scenario_id'] ?? '') !== $scenarioId || ($payload['worker_id'] ?? '') !== $id || (int) ($payload['call_begin_ns'] ?? -1) !== 0) { throw new RuntimeException('BARRIER_PROTOCOL_INVALID_READY'); } $index = $id === 'A' ? 0 : 1; if (($payload['fixture_fingerprint'] ?? '') !== $fixtureFingerprint((int) $workers[$index][0], (int) $workers[$index][1], (string) $workers[$index][2])) { throw new RuntimeException('BARRIER_PROTOCOL_FIXTURE_DRIFT'); } } $go = $dir . DIRECTORY_SEPARATOR . 'go.json'; file_put_contents($go . '.tmp', json_encode(array('run_id' => $runId, 'scenario_id' => $scenarioId))); rename($go . '.tmp', $go); $results = array(); foreach ($procs as $z) $results[] = $collect($z[0], $z[1]); foreach ($results as $result) { if (!isset($result['call_begin_ns'], $result['call_end_ns']) || !$result['call_begin_ns'] || !$result['call_end_ns']) { throw new RuntimeException('BARRIER_PROTOCOL_MISSING_TIMING'); } } $a = $results[0]; $b = $results[1]; $deltaMs = abs((int) $a['call_begin_ns'] - (int) $b['call_begin_ns']) / 1000000; if ($deltaMs > 1000 || !((int) $a['call_begin_ns'] < (int) $b['call_end_ns'] && (int) $b['call_begin_ns'] < (int) $a['call_end_ns'])) { throw new RuntimeException('BARRIER_PROTOCOL_NO_OVERLAP'); } return $results; } finally { foreach ($procs as $z) { if (is_resource($z[0]) && proc_get_status($z[0])['running']) { proc_terminate($z[0]); } foreach ($z[1] as $h) { if (is_resource($h)) @fclose($h); } if (is_resource($z[0])) @proc_close($z[0]); } foreach (glob($dir . DIRECTORY_SEPARATOR . '*') ?: array() as $path) { if (is_file($path)) @unlink($path); } @rmdir($dir); } };
$runRace = function ($requestId, $actorA, $actorB, $keyA, $keyB, $mode = 'non_visit') use ($barrierRace) { return $barrierRace(array(array($requestId, $actorA, $mode, $keyA), array($requestId, $actorB, $mode, $keyB))); };
$runDifferentRequestsRace = function ($requestA, $requestB, $actorA, $actorB, $key) use ($barrierRace) { return $barrierRace(array(array($requestA, $actorA, 'non_visit', $key), array($requestB, $actorB, 'non_visit', $key))); };
$make($base + 10, $base + 2, 't10c-d1-' . $base); $same = $runRace($base + 10, $actor, $actor, 't10c-same-' . $base, 't10c-same-' . $base); vcw_assert_same('success', $same[0]['status'] ?? null, 'same-key winner'); vcw_assert_same('success', $same[1]['status'] ?? null, 'same-key replay'); vcw_assert_same(1, (int) $db->where('request_id', $base + 10)->count_all_results('clinical_closure_operations'), 'one same-key receipt');
$row = $db->select('request_status')->where('request_id', $base + 10)->get('requests')->row_array(); vcw_assert_same('Completed', $row['request_status'] ?? null, 'same-key request completed'); vcw_assert_same(1, (int) $db->where('domain_event_key', 'request:' . ($base + 10) . ':clinical-closed')->count_all_results('request_events'), 'one same-key event');
$make($base + 11, $base + 2, 't10c-d2-' . $base); $different = $runRace($base + 11, $actor, $actor, 't10c-k1-' . $base, 't10c-k2-' . $base); $statuses = array($different[0]['status'] ?? '', $different[1]['status'] ?? ''); vcw_assert_same(1, count(array_filter($statuses, function ($s) { return $s === 'success'; })), 'different-key one winner'); vcw_assert_true(in_array('CLINICAL_ALREADY_CLOSED', array($different[0]['safe_error_code'] ?? '', $different[1]['safe_error_code'] ?? ''), true), 'different-key loser');
$row = $db->select('request_status')->where('request_id', $base + 11)->get('requests')->row_array(); vcw_assert_same('Completed', $row['request_status'] ?? null, 'different-key request completed'); vcw_assert_same(1, (int) $db->where('request_id', $base + 11)->count_all_results('clinical_closure_operations'), 'different-key one receipt'); vcw_assert_same(1, (int) $db->where('domain_event_key', 'request:' . ($base + 11) . ':clinical-closed')->count_all_results('request_events'), 'different-key one event');
$make($base + 12, $base + 2, 't10c-d3-' . $base); $globalKey = 't10c-global-' . $base; $make($base + 13, $base + 2, 't10c-d4-' . $base); $global = $runDifferentRequestsRace($base + 12, $base + 13, $actor, $actor, $globalKey); $globalCodes = array($global[0]['safe_error_code'] ?? '', $global[1]['safe_error_code'] ?? ''); vcw_assert_same(1, count(array_filter(array($global[0]['status'] ?? '', $global[1]['status'] ?? ''), function ($s) { return $s === 'success'; })), 'global key one success ' . json_encode($global)); vcw_assert_true(in_array('CLOSURE_KEY_CONFLICT', $globalCodes, true), 'global key conflict loser ' . json_encode($global)); vcw_assert_same(1, (int) $db->where('idempotency_key', $globalKey)->count_all_results('clinical_closure_operations'), 'global key one owner');
$globalStatuses = array(); foreach (array($base + 12, $base + 13) as $requestId) { $globalStatuses[] = $db->select('request_status')->where('request_id', $requestId)->get('requests')->row('request_status'); } vcw_assert_same(1, count(array_filter($globalStatuses, function ($s) { return $s === 'Completed'; })), 'global one completed request'); vcw_assert_same(1, count(array_filter($globalStatuses, function ($s) { return $s === 'Accepted'; })), 'global loser remains accepted');
echo "TASK10_CLOSURE_SAME_KEY_RACE=PASS\nTASK10_CLOSURE_DIFFERENT_KEY_RACE=PASS\nTASK10_CLOSURE_GLOBAL_KEY_COLLISION=PASS\n";
