$db->query('INSERT INTO requests (request_id,user_id,location,request_status,assigned_puskesmas_code,assigned_puskesmas_name,visit_status,consultation_mode,responsible_doctor_user_id,visit_performer_user_id) VALUES (?,?,?,?,?,?,?,?,?,?)', array($m, $mrd, 'synthetic', 'Accepted', $mfac, 'Task 10 Mixed Race', 'completed', 'visit', $mrd, $mperf)); $db->query('INSERT INTO request_responsible_doctor_assignments (request_id,staff_id,user_id,assigned_by_user_id,status,assigned_at) VALUES (?,?,?,?,?,NOW(6))', array($m, $mrd, $mrd, $mrd, 'aktif')); $mra = (int)$db->insert_id(); $db->query('INSERT INTO visit_dispositions (request_id,version_no,decision,urgency,created_by_user_id,idempotency_key,created_at) VALUES (?,?,?,?,?,?,NOW(6))', array($m,1,'visit','routine',$mrd,'t10m-disp-'.$m)); $db->query('INSERT INTO request_visit_performer_assignments (request_id,staff_id,user_id,assigned_by_user_id,status,assigned_at,completed_at) VALUES (?,?,?,?,?,NOW(6),NOW(6))', array($m,$mperf,$mperf,$mrd,'selesai')); $mva=(int)$db->insert_id(); $db->query("INSERT INTO visit_results (request_id,visit_assignment_id,version_no,performer_user_id,performer_staff_id,status,draft_revision,findings_json,actions_json,created_at,updated_at,submitted_at,submitted_by_user_id,submission_key) VALUES (?,?,?,?,?,'submitted',0,'[]','[]',NOW(6),NOW(6),NOW(6),?,?)", array($m,$mva,$mperf,$mperf,$mperf,$mperf,'t10m-result-'.$m)); $mres=(int)$db->insert_id(); $db->query('INSERT INTO clinical_reviews (request_id,visit_result_id,reviewer_user_id,responsible_assignment_id,reviewer_visit_assignment_id,decision,reviewed_at,idempotency_key) VALUES (?,?,?,?,?,?,NOW(6),?)', array($m,$mres,$mrd,$mra,null,'approved','t10m-review-'.$m)); $db->query('INSERT INTO medicalrecords (request_id,diagnosis,treatment,recommendations,anamnesis,responsible_doctor_user_id,recorded_by_user_id,clinical_finalized_at,clinical_finalized_by_user_id) VALUES (?,?,?,?,?,?,?,NOW(6),?)', array($m,'initial','initial','initial','history',$mrd,$mrd,$mrd)); $mrec=(int)$db->insert_id();
$mixedRace = function () use ($m, $mperf, $mrd, $mrec, $collect, $fixtureFingerprint, $db) { $run=bin2hex(random_bytes(8));$scenario='mixed-'.bin2hex(random_bytes(5));$dir=sys_get_temp_dir().DIRECTORY_SEPARATOR.'doclinc-mixed-'.$run;$env=getenv();$trigger='t10_mixed_delay_'.$run;mkdir($dir,0700,true);$procs=[];try{$db->query("DROP TRIGGER IF EXISTS {$trigger}");$db->query("CREATE TRIGGER {$trigger} BEFORE INSERT ON clinical_closure_operations FOR EACH ROW BEGIN IF NEW.request_id = {$m} THEN DO SLEEP(0.25); END IF; END");foreach([['closure',__DIR__.'/clinical_closure_worker.php',[$m,$mperf,'visit','t10m-close-'.$m]],['amendment',__DIR__.'/clinical_closure_amendment_worker.php',[$m,$mrec,$mrd,'t10m-amend-'.$m,'race','corrected']]] as $i=>$w){$id=$i===0?'A':'B';$e=array_merge($env,['TASK10_BARRIER_DIR'=>$dir,'TASK10_RUN_ID'=>$run,'TASK10_SCENARIO_ID'=>$scenario,'TASK10_WORKER_ID'=>$id]);$pipes=[];$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg($w[1]).' '.implode(' ',array_map('escapeshellarg',$w[2]));$procs[]=[$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,__DIR__,$e),$pipes];}$ready=[];$d=microtime(true)+10;while(microtime(true)<$d&&count($ready)<2){foreach(['A','B'] as $id){$p=$dir.'/ready-'.$id.'.json';if(is_file($p)&&!isset($ready[$id]))$ready[$id]=json_decode(file_get_contents($p),true);}if(count($ready)<2)usleep(10000);}if(count($ready)!==2)throw new RuntimeException('MIXED_READY');$expected=[ 'A'=>['operation'=>'closure','request_id'=>$m,'user_id'=>$mperf,'mode'=>'visit'], 'B'=>['operation'=>'amendment','request_id'=>$m,'user_id'=>$mrd,'mode'=>'visit'] ];foreach($ready as $id=>$x){if(!is_array($x)||($x['run_id']??'')!==$run||($x['scenario_id']??'')!==$scenario||($x['worker_id']??'')!==$id||($x['operation']??'')!==$expected[$id]['operation']||($x['request_id']??0)!==$expected[$id]['request_id']||($x['user_id']??0)!==$expected[$id]['user_id']||($x['mode']??'')!==$expected[$id]['mode']||($x['call_begin_ns']??-1)!==0||!hash_equals($fixtureFingerprint($expected[$id]['request_id'],$expected[$id]['user_id'],'visit'),(string)($x['fixture_fingerprint']??'')))throw new RuntimeException('MIXED_READY_INVALID');}$g=$dir.'/go.json';file_put_contents($g.'.tmp',json_encode(['run_id'=>$run,'scenario_id'=>$scenario]));rename($g.'.tmp',$g);$r=[];foreach($procs as $z)$r[]=$collect($z[0],$z[1]);foreach($r as $x)if(($x['status']??'')!=='success'||empty($x['call_begin_ns'])||empty($x['call_end_ns']))throw new RuntimeException('MIXED_RESULT ' . json_encode($r));if(!((int)$r[0]['call_begin_ns']<(int)$r[1]['call_end_ns']&&(int)$r[1]['call_begin_ns']<(int)$r[0]['call_end_ns']))throw new RuntimeException('MIXED_OVERLAP');return $r;}finally{$db->query("DROP TRIGGER IF EXISTS {$trigger}");foreach($procs as $z){if(is_resource($z[0])&&proc_get_status($z[0])['running'])proc_terminate($z[0]);foreach($z[1] as $h)if(is_resource($h))@fclose($h);if(is_resource($z[0]))@proc_close($z[0]);}foreach(glob($dir.'/*')?:[] as $p)@unlink($p);@rmdir($dir);}};
$mixed = $mixedRace(); vcw_assert_same(1, (int)$db->where('request_id',$m)->count_all_results('clinical_closure_operations'), 'mixed one receipt'); vcw_assert_same(1, (int)$db->where('record_id',$mrec)->count_all_results('clinical_amendments'), 'mixed amendment persisted'); vcw_assert_same('Completed', (string)$db->select('request_status')->where('request_id',$m)->get('requests')->row()->request_status, 'mixed completed'); vcw_assert_same(1, (int)$db->where('request_id',$m)->where('domain_event_key','request:'.$m.':clinical-closed')->count_all_results('request_events'), 'mixed one closure event'); vcw_assert_same(1, (int)$db->where('request_id',$m)->where('event_type','clinical_record.amended')->count_all_results('request_events'), 'mixed one amendment event'); $mixedReceipt=$db->where('request_id',$m)->get('clinical_closure_operations')->row(); vcw_assert_same($mperf,(int)$mixedReceipt->closed_by_user_id,'mixed closure actor'); vcw_assert_same('doctor_visit_performer',(string)$mixedReceipt->authority_source,'mixed closure provenance'); vcw_assert_same($mrd,(int)$db->where('amendment_id',(int)$db->where('record_id',$mrec)->get('clinical_amendments')->row()->amendment_id)->get('clinical_amendments')->row()->created_by_user_id,'mixed amendment actor'); echo "TASK10_CLOSURE_VS_AMENDMENT=PASS\nTASK10_CLOSURE_CONCURRENCY=PASS\n";
